ALTER TABLE `risk_findings` ADD COLUMN `excluded_reason` LowCardinality(String) DEFAULT '' COMMENT 'Why the finding was suppressed: rule (exclusion rule, exclusion_id set), manual (dismissed by a user via UI or agent tool) or automated (offline false-positive sweep). Empty when the finding is not suppressed or on legacy rows written before this column existed.';
ALTER TABLE `risk_findings` ADD COLUMN `excluded_detail` String DEFAULT '' COMMENT 'Free-form context for the suppression: the user-supplied dismissal reason for manual rows, the false-positive catalog reason for automated rows. Empty for rule rows and when no reason was given.' CODEC(ZSTD(1));
